import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert, Button } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE ===================== */
const themeStyle = `
  .chart-scroll { overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; }
  
  .history-header {
    background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
    border-radius: 8px 8px 0 0 !important;
    padding: 20px !important;
  }
  
  .history-header .card-title { 
    color: white !important; 
    margin: 0 !important; 
    font-weight: bold; 
    font-size: 1.25rem; 
  }
  
  .form-select { 
    border-radius: 12px !important; 
    padding: 8px 15px !important; 
    border: 1px solid #e9ecef !important; 
    font-size: 14px !important; 
    color: #525f7f !important; 
  }
  
  .form-label { 
    font-weight: 700; 
    color: #5e72e4; 
    text-transform: uppercase; 
    font-size: 0.75rem; 
    margin-bottom: 8px; 
  }
  
  .card { 
    border: none !important; 
    box-shadow: 0 0 2rem 0 rgba(136, 152, 170, 0.15) !important; 
    margin-bottom: 30px !important; 
    border-radius: 0.75rem !important; 
  }
  
  .ct-bar { cursor: pointer; transition: opacity 0.2s; }
  .ct-bar:hover { opacity: 0.7; }
  
  .legend-dot { 
    width: 12px; height: 12px; 
    border-radius: 50%; 
    display: inline-block; 
    margin-right: 5px; 
  }

  .ct-label.ct-horizontal {
    padding-top: 10px !important;
  }
`;

const CAMERA_MAP = {
  CAM01: "วิศวะ",
  CAM02: "วิทยาศาสตร์",
  CAM03: "ศิลปศาสตร์",
  CAM04: "PKY"
};

function History() {

  const currentYearBE = new Date().getFullYear() + 543;

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth()+1).toString().padStart(2,"0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());

  const [cameraId, setCameraId] = useState("CAM01");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");

  const [rawFileData, setRawFileData] = useState({ labels: [], series: [[]] });
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });

  const [detailChart, setDetailChart] = useState(null);
  const [selectedHour, setSelectedHour] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const monthsThai = [
    { val:"01", name:"มกราคม"},
    { val:"02", name:"กุมภาพันธ์"},
    { val:"03", name:"มีนาคม"},
    { val:"04", name:"เมษายน"},
    { val:"05", name:"พฤษภาคม"},
    { val:"06", name:"มิถุนายน"},
    { val:"07", name:"กรกฎาคม"},
    { val:"08", name:"สิงหาคม"},
    { val:"09", name:"กันยายน"},
    { val:"10", name:"ตุลาคม"},
    { val:"11", name:"พฤศจิกายน"},
    { val:"12", name:"ธันวาคม"}
  ];

  const timeOptions = Array.from({ length:16 }, (_,i)=>{
    const hour = (i+7).toString().padStart(2,"0")+":00";
    return <option key={hour} value={hour}>{hour}</option>
  });

  const handleSearch = async () => {

    setIsLoaded(false);
    setDetailChart(null);

    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2,"0")}`;

    try {

      const res = await fetch(`http://localhost:3001/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);

      const result = await res.json();

      if(result && result.labels.length>0){

        setRawFileData(result);

        const bucket = {};

        result.labels.forEach((label,idx)=>{

          const hour = label.split(":")[0].padStart(2,"0")+":00";

          if(!bucket[hour]) bucket[hour] = {sum:0,count:0};

          bucket[hour].sum += result.series[0][idx];
          bucket[hour].count += 1;

        });

        const labels=[];
        const series=[];

        const startH=parseInt(startTime.split(":")[0]);
        const endH=parseInt(endTime.split(":")[0]);

        for(let i=startH;i<=endH;i++){

          const h=i.toString().padStart(2,'0')+":00";

          labels.push(h);

          series.push(bucket[h] ? Math.round(bucket[h].sum / bucket[h].count) : 0);
        }

        setChartState({labels,series:[series]});

      }else{

        setChartState({labels:[],series:[[]]});
        setRawFileData({labels:[],series:[[]]});
      }

    }catch(err){

      console.error(err);

    }finally{

      setIsLoaded(true);
    }
  };

  useEffect(()=>{

    handleSearch();

  },[selectedDay,selectedMonth,selectedYearBE,cameraId,startTime,endTime]);

  const getDensityColor = (val)=>{
    if(val>=41) return "#f5365c";
    if(val>=31) return "#fb6340";
    if(val>=21) return "#ffd600";
    return "#2dce89";
  };

  /* ===================== BAR CLICK EVENT ===================== */

  const chartEvents={

    draw:(data)=>{

      if(data.type==="bar"){

        data.element.attr({
          style:`stroke:${getDensityColor(data.value.y)};stroke-width:25px`
        });

        data.group.elem("text",{
          x:data.x2,
          y:data.y2-15,
          style:"font-size:12px;font-weight:bold;text-anchor:middle;fill:#525f7f"
        }).text(data.value.y);

      }
    },

    created:(context)=>{

      context.svg._node.onclick=(e)=>{

        const bar=e.target.closest(".ct-bar");
        if(!bar) return;

        const bars=[...bar.parentNode.querySelectorAll(".ct-bar")];
        const index=bars.indexOf(bar);

        if(index===-1) return;

        const hourLabel=chartState.labels[index];

        /* ===== รวมค่าเฉลี่ยรายนาที ===== */

        const minuteBucket={};

        rawFileData.labels.forEach((label,i)=>{

          if(label.startsWith(hourLabel.split(":")[0])){

            const minute = label.substring(0,5);

            if(!minuteBucket[minute])
              minuteBucket[minute]={sum:0,count:0};

            minuteBucket[minute].sum += rawFileData.series[0][i];
            minuteBucket[minute].count += 1;

          }

        });

        const dLabels=[];
        const dSeries=[];

        Object.keys(minuteBucket).sort().forEach(min=>{

          dLabels.push(min);

          dSeries.push(
            Math.round(
              minuteBucket[min].sum /
              minuteBucket[min].count
            )
          );

        });

        if(dLabels.length>0){

          setSelectedHour(hourLabel);

          setDetailChart({
            labels:dLabels,
            series:[dSeries]
          });

        }

      };

    }

  };

  const lineChartEvents={
    draw:(data)=>{

      if(data.type==="line"){
        data.element.attr({
          style:"stroke:#ced4da;stroke-width:3px"
        });
      }

      if(data.type==="area"){
        data.element.attr({
          style:"fill:#e9ecef;fill-opacity:0.5"
        });
      }

      if(data.type==="point"){

        const color=getDensityColor(data.value.y);

        data.element.attr({
          style:`stroke:${color};stroke-width:12px`
        });

        data.group.elem("text",{
          x:data.x,
          y:data.y-18,
          style:`font-size:14px;font-weight:bold;text-anchor:middle;fill:${color}`
        }).text(data.value.y);

      }

    }
  };

  return (

    <Container fluid className="py-4">

      <style>{themeStyle}</style>

      <Row>

        <Col md="12">

          <Card>

            <Card.Header className="history-header">
              <Card.Title as="h4">ข้อมูลย้อนหลัง</Card.Title>
            </Card.Header>

            <Card.Body className="px-4 py-4">

              <Row className="align-items-end g-3">

                <Col md="3">

                  <Form.Label className="form-label">เลือกสถานที่</Form.Label>

                  <Form.Select
                    value={cameraId}
                    onChange={(e)=>setCameraId(e.target.value)}
                  >
                    {Object.entries(CAMERA_MAP).map(([k,v])=>
                      <option key={k} value={k}>{v}</option>
                    )}
                  </Form.Select>

                </Col>

                <Col md="4">

                  <Form.Label className="form-label">ช่วงเวลา</Form.Label>

                  <div className="d-flex gap-2">

                    <Form.Select value={startTime} onChange={(e)=>setStartTime(e.target.value)}>
                      {timeOptions}
                    </Form.Select>

                    <Form.Select value={endTime} onChange={(e)=>setEndTime(e.target.value)}>
                      {timeOptions}
                    </Form.Select>

                  </div>

                </Col>

              </Row>

            </Card.Body>

          </Card>

        </Col>

      </Row>

      {detailChart && (

        <Card className="mt-3">

          <Card.Header>
            🔍 รายละเอียดรายนาที {selectedHour}
          </Card.Header>

          <Card.Body>

            <div className="chart-scroll">

              <div style={{width:"100%",minWidth:"1200px",height:"350px"}}>

                <ChartistGraph
                  data={detailChart}
                  type="Line"
                  options={{
                    low:0,
                    showArea:true,
                    fullWidth:true,
                    axisX:{
                      labelInterpolationFnc:(value,index)=> index%5===0 ? value : null
                    },
                    axisY:{onlyInteger:true}
                  }}
                  listener={lineChartEvents}
                />

              </div>

            </div>

          </Card.Body>

        </Card>

      )}

    </Container>

  );

}

export default History;
